WITH v1 AS (
  SELECT replay.strict_oos.raw_fire_rate AS v1_raw_fire_rate
  FROM read_json_auto('analysis/output/eth3m_short_pilot_v1_backtest/summary.json')
), v2 AS (
  SELECT totals.total AS v2_images, totals.independent_positive_events AS v2_positive_events,
         totals.sealed_smoke_bars AS v2_smoke_bars, split_audit.anchor_embargo_bars AS v2_embargo_bars
  FROM read_json_auto('datasets/eth_3m_short_pilot_v2/build_meta.json')
)
SELECT * FROM v1 CROSS JOIN v2;

